export const GENERATED_MARKER =
	'<!-- Generated by sv migrate sveltekit-3:collect-migration-instructions -->';

type MigrationTask = {
	title: string;
	checks?: Array<{
		include: string | string[];
		patterns: Array<string | RegExp>;
	}>;
	summary: string;
	instructions: string;
	links: Array<{ label: string; url: string }>;
};

function guideLink(anchor: string): MigrationTask['links'] {
	return [{ label: 'Migrating to SvelteKit v3', url: `${GUIDE_URL}#${anchor}` }];
}

